(6389318, 946879, 15711, '<td valign="top">WOW - this is an absolutely stunning image.  I wonder though with the blur of the others, if it doesn''t quite suit the "rules" of the challenge. If the focused flower were the only thing yellow, to me, it would offset it as the subject more. If this were in a free study, I''d give it a 10 hands down.  This needs to be hung on a wall, HUGE, or on canvas.  I love it.</td>', 'WOW - this is an absolutely stunning image.  I wonder though with the blur of the others, if it doesn''t quite suit the "rules" of the challenge. If the focused flower were the only thing yellow, to me, it would offset it as the subject more. If this were in a free study, I''d give it a 10 hands down.  This needs to be hung on a wall, HUGE, or on canvas.  I love it.', '2011-04-18 10:34:00.000000', NULL, 1),
(6389319, 946704, 15711, '<td valign="top">I do not like reptiles, but this is beautifully presented. Perfect light and shadow.</td>', 'I do not like reptiles, but this is beautifully presented. Perfect light and shadow.', '2011-04-18 10:34:55.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6389328, 946023, 54833, '<td valign="top">I would prefer the shot rotated to where the butterfly is right side up, but a great capture. Nice focus</td>', 'I would prefer the shot rotated to where the butterfly is right side up, but a great capture. Nice focus', '2011-04-18 10:51:43.000000', NULL, 1),
(6389334, 946532, 54833, '<td valign="top">Really cool, a little creepy,but nice shot.</td>', 'Really cool, a little creepy,but nice shot.', '2011-04-18 10:57:28.000000', NULL, 1),
(6389337, 946513, 54833, '<td valign="top">The body paint is great, wish she were turned a little more towards the camera and that there was so much going on behind her.</td>', 'The body paint is great, wish she were turned a little more towards the camera and that there was so much going on behind her.', '2011-04-18 11:01:41.000000', NULL, 1),
(6389383, 946879, 33068, '<td valign="top">WOW!  This stopped me dead in my tracks. When the challenge is over, I''d love to know what lens you used and your processing?  This is stunning.   10</td>', 'WOW!  This stopped me dead in my tracks. When the challenge is over, I''d love to know what lens you used and your processing?  This is stunning.   10', '2011-04-18 12:09:17.000000', NULL, 1),
(6389385, 946798, 33068, '<td valign="top">Love the composition and processing.  Nice work and idea.</td>', 'Love the composition and processing.  Nice work and idea.', '2011-04-18 12:10:07.000000', NULL, 1),
(6389386, 946706, 131018, '<td valign="top">Love the simplicity of this.</td>', 'Love the simplicity of this.', '2011-04-18 12:10:14.000000', NULL, 1),
(6389389, 946320, 33068, '<td valign="top">I think I know who this is. :) Great image and very well executed.</td>', 'I think I know who this is. :) Great image and very well executed.', '2011-04-18 12:11:51.000000', NULL, 1),
(6389395, 946585, 124346, '<td valign="top">Wow, beautiful, amazing, dynamic, this is a winner, I tell you.  It''s a shame I can''t vote in this challenge, if so, I''ll give it a 10.</td>', 'Wow, beautiful, amazing, dynamic, this is a winner, I tell you.  It''s a shame I can''t vote in this challenge, if so, I''ll give it a 10.', '2011-04-18 12:15:59.000000', NULL, 1),
(6389396, 946851, 124346, '<td valign="top">Wow, it''s an interesting photo.  How did you get all the stars as a spot and not as a trail?  High ISO?</td>', 'Wow, it''s an interesting photo.  How did you get all the stars as a spot and not as a trail?  High ISO?', '2011-04-18 12:19:04.000000', NULL, 1),
(6389398, 946320, 124346, '<td valign="top">Too perfect, the rainbow, the cute little girl with the big boots and the big umbrella.</td>', 'Too perfect, the rainbow, the cute little girl with the big boots and the big umbrella.', '2011-04-18 12:24:55.000000', NULL, 1),
(6389400, 946637, 123348, '<td valign="top">That''s really cool! :)9</td>', 'That''s really cool! :)9', '2011-04-18 12:29:22.000000', NULL, 1),
(6389402, 946705, 124346, '<td valign="top">Try to take this picture and cut the lower third of it, in order to eliminate the people on the ground.  Could be a nice result, and the people on the wheel (not sure if that how you call it) would become the subjet of the photo.  It''d look nice as the people would be looking at the city from above.</td>', 'Try to take this picture and cut the lower third of it, in order to eliminate the people on the ground.  Could be a nice result, and the people on the wheel (not sure if that how you call it) would become the subjet of the photo.  It''d look nice as the people would be looking at the city from above.', '2011-04-18 12:35:54.000000', NULL, 1),
(6389403, 946414, 124346, '<td valign="top">Nice.</td>', 'Nice.', '2011-04-18 12:36:10.000000', NULL, 1),
(6389412, 946726, 124346, '<td valign="top">I''m making a lightbox myself.  I hope I can take great pictures as yours.  I don''t know if you are the same person as the one who took a picture of cups like this but with the liquid at a side.  Do you have a recommendation for me, for taking pictures in a lightbox?</td>', 'I''m making a lightbox myself.  I hope I can take great pictures as yours.  I don''t know if you are the same person as the one who took a picture of cups like this but with the liquid at a side.  Do you have a recommendation for me, for taking pictures in a lightbox?', '2011-04-18 12:41:48.000000', NULL, 1),
(6389415, 946703, 124346, '<td valign="top">Yuujjjuuuuuuuu!!!!!!!!!!! Nice one.</td>', 'Yuujjjuuuuuuuu!!!!!!!!!!! Nice one.', '2011-04-18 12:43:58.000000', NULL, 1),
(6389419, 946033, 124346, '<td valign="top">I like the effect on the picture, how do you get it?</td>', 'I like the effect on the picture, how do you get it?', '2011-04-18 12:45:44.000000', NULL, 1),
(6389424, 946854, 124346, '<td valign="top">Crazy one, nice.</td>', 'Crazy one, nice.', '2011-04-18 12:54:44.000000', NULL, 1),
(6389431, 946711, 5112, '<td valign="top">Beautiful, but I think that the drop is (1) just a bit too small to command enough attention, and (2) it needs to show sharpness better to work.  I like the purple/yellow colour scheme.  More than "burst of colour" this is "compo on colour".  ~7</td>', 'Beautiful, but I think that the drop is (1) just a bit too small to command enough attention, and (2) it needs to show sharpness better to work.  I like the purple/yellow colour scheme.  More than "burst of colour" this is "compo on colour".  ~7', '2011-04-18 13:00:52.000000', NULL, 1),
(6389433, 946349, 5112, '<td valign="top">My opinion, but I would have worked at not having shadows on a stop sign, and second, I think there''s a bit too much space at right and not enough at bottom an left.  Even just lining up the right side close to the sign, as you have it at bottom now, might work better.  Not sure though.  ~6</td>', 'My opinion, but I would have worked at not having shadows on a stop sign, and second, I think there''s a bit too much space at right and not enough at bottom an left.  Even just lining up the right side close to the sign, as you have it at bottom now, might work better.  Not sure though.  ~6', '2011-04-18 13:02:01.000000', NULL, 1),
